def student(name):
    return importlib.import_module(name)


def describe(exc):
    if isinstance(exc, NotImplementedError):
        return "not implemented yet"
    if isinstance(exc, SyntaxError) and exc.filename and exc.lineno:
        from hw2lib.notebook import location
        where = location(exc.filename, exc.lineno)
        if where:
            return f"{type(exc).__name__} in {where}: {exc.msg}"
    if isinstance(exc, AttributeError) and getattr(exc, "obj", None) is not None \
            and type(exc.obj).__name__ == "module" and exc.obj.__name__ in STUDENT_MODULES:
        return (f"{exc.name} is not defined in any '# GRADED: {exc.obj.__name__}' cell "
                f"(check the first line of the cell that defines it)")
    if isinstance(exc, NameError):
        return (f"NameError: {exc} (everything a graded function uses must be defined in a "
                f"GRADED cell; ungraded cells are not part of your submission)")
    if isinstance(exc, RecursionError):
        return "RecursionError: maximum recursion depth exceeded (an infinite recursion?)"
    return f"{type(exc).__name__}: {exc}"


def run_cases(cases, check, limit=3):
    """Run check(case) -> None or a failure message on each case. Failures of public
    cases are described (up to `limit`); failures of hidden cases are only counted, so
    that the expected outputs of hidden cases are never shown."""
    passed, messages, hidden_failed = 0, [], 0
    for case in cases:
        try:
            problem = check(case)
        except Exception as exc:  # noqa: BLE001 - student code may raise anything
            problem = describe(exc)
        if problem is None:
            passed += 1
        elif case.get("hidden"):
            hidden_failed += 1
        elif len(messages) < limit and problem not in messages:
            messages.append(problem)
    if hidden_failed:
        messages.append(f"{hidden_failed} hidden case(s) failed (hidden cases are not shown).")
    return passed, len(cases), messages


def short(value, limit=300):
    text = repr(value)
    return text if len(text) <= limit else text[:limit] + " ..."


class TookTooLong(Exception):
    pass


class alarm:
    """Interrupt the block after `seconds` where the OS supports SIGALRM (Linux, macOS)."""

    def __init__(self, seconds):
        self.seconds = seconds
        self.active = hasattr(signal, "SIGALRM")

    def _fire(self, signum, frame):
        raise TookTooLong(f"stopped after {self.seconds} s")

    def __enter__(self):
        if self.active:
            self.old = signal.signal(signal.SIGALRM, self._fire)
            signal.setitimer(signal.ITIMER_REAL, self.seconds)

    def __exit__(self, *exc):
        if self.active:
            signal.setitimer(signal.ITIMER_REAL, 0)
            signal.signal(signal.SIGALRM, self.old)
        return False


