# Answers

ABCD = ("A", "B", "C", "D")

# name: (group, points, kind, extra)
ANSWER_ITEMS = {
    "P1A": ("answers_p1", 5, "number", None),
    "P1B": ("answers_p1", 5, "number", None),
    "P1C": ("answers_p1", 5, "number", None),
    "P2A": ("answers_p2", 5, "number", None),
    "P2B": ("answers_p2", 5, "choice", ABCD),
    "P3D1": ("answers_p3", 3, "choice", ABCD),
    "P3D2": ("answers_p3", 3, "choice", ABCD),
    "P3D3": ("answers_p3", 3, "choice", ABCD),
    "P3D4": ("answers_p3", 3, "choice", ABCD),
    "P3D5": ("answers_p3", 3, "choice", ABCD),
}
NUMBER_TOLERANCE = 0.001   # relative error


def format_problem(kind, value, extra):
    """Why value has the wrong format for this kind of answer, or None."""
    if value is None:
        return "still None"
    if kind == "number":
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
            return f"must be a number, not {value!r}"
        return None
    if kind == "choice":
        if value not in extra:
            return f"must be one of {', '.join(repr(e) for e in extra)}, not {value!r}"
        return None
    raise ValueError(kind)


def grade_answers(group, key=None):
    """With key=None (check() in the notebook), only formats are checked."""
    try:
        mod = student("answers")
    except Exception as exc:  # noqa: BLE001
        return 0, [f"the answers could not be imported: {describe(exc)}"]
    points, messages = 0.0, []
    for name, (g, worth, kind, extra) in ANSWER_ITEMS.items():
        if g != group:
            continue
        value = getattr(mod, name, None)
        problem = format_problem(kind, value, extra)
        if problem is not None:
            messages.append(f"{name}: {problem}  [0/{worth}]")
            continue
        if key is None:
            messages.append(f"{name}: format OK")
            continue
        want = key[name]
        ok = abs(value - want) <= NUMBER_TOLERANCE * abs(want) if kind == "number" else value == want
        got = worth if ok else 0
        points += got
        messages.append(f"{name}: {'correct' if ok else 'incorrect'}  [{got:g}/{worth}]")
    return round(points, 4), messages
